import json,os
G={}
def load():
    import os,re
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
load(); print(sorted(G))

def f(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    pts={}
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (g[0][0],0):
                pts.setdefault(g[r][c],[]).append((r,c))
    bg=g[0][0]
    for col,p in pts.items():
        p.sort()
        if len(p)<2: continue
        (r1,c1),(r2,c2)=p[-2],p[-1]
        dr,dc=r2-r1,c2-c1
        # normalize step
        s=(dr//abs(dr) if dr else 0, dc//abs(dc) if dc else 0)
        r,c=r2+s[0],c2+s[1]
        while 0<=r<h and 0<=c<w:
            out[r][c]=col; r+=s[0]; c+=s[1]
    return out

